import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+'
    urls = re.findall(url_pattern, myString)

    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        if parsed.netloc:
            domains.add(parsed.netloc)

    results = {}
    for domain in domains:
        try:
            response = requests.get(f"http://ip-api.com/json/{domain}")
            if response.status_code == 200:
                results[domain] = response.json()
            else:
                results[domain] = None
        except requests.RequestException:
            results[domain] = None

    return results

