import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError:
            raise ValueError("Invalid JSON format")

    for req in INPUT_JSON["required"]:
        if req not in data:
            raise ValueError(f"Missing required attribute: {req}")

    for key, value in data.items():
        if key in INPUT_JSON["properties"]:
            expected_type = INPUT_JSON["properties"][key]["type"]
            if not isinstance(value, expected_type):
                raise ValueError(f"Type mismatch for {key}")

    if "email" in data and not re.match(EMAIL_REGEX, data["email"]):
        raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute {attribute} not found")

    return data[attribute]

